import React from 'react';
import MainHeading from '../../../Components/Heading/MainHeading';
import NavBar from '../../../Components/NavBar/NavBar';
import bgVideo from "./../back.mp4"
// import solarImage from "./../solar.webp"
// import s2Back from "./../pexels-kaip-1341279.jpg"

function Section1() {
  return (
    <>
    <div className="relative w-full h-screen">
    <video
      className="absolute top-0 left-0 w-full h-full object-cover"
      autoPlay
      loop
      muted
      >
      <source src={bgVideo} type="video/mp4" />
      Your browser does not support the video tag.
    </video>
    <div className="relative font-poppins z-10  items-center justify-center flex w-full h-full bg-black bg-opacity-20">
      <NavBar  />
      <h1 className="text-white text-7xl font-bold text-center uppercase">Explore The Solar System</h1>
    </div>
  </div>
  
      </>
  )
}

export default Section1
